import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"The Kernel Is the Evaluator, Not the Calculus","description":"","frontmatter":{"title":"The Kernel Is the Evaluator, Not the Calculus","type":"adr","date":"2026-09-10T00:00:00.000Z","status":"accepted","status_note":"Accepted — the kernel is a bytecode VM; the calculus lives in handl models."},"headers":[],"relativePath":"handl/project/adrs/0103-kernel-is-evaluator-not-calculus.md","filePath":"vendored/handl/project/adrs/0103-kernel-is-evaluator-not-calculus.md"}`),a={name:`handl/project/adrs/0103-kernel-is-evaluator-not-calculus.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0103-the-kernel-is-the-evaluator-not-the-calculus" tabindex="-1">ADR-0103: The Kernel Is the Evaluator, Not the Calculus <a class="header-anchor" href="#adr-0103-the-kernel-is-the-evaluator-not-the-calculus" aria-label="Permalink to “ADR-0103: The Kernel Is the Evaluator, Not the Calculus”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>The kernel is the evaluator, not the calculus</strong>: a bytecode VM over values, with no named-op surface.</li><li><strong>The ISA is small and structural</strong>; anything expressible as data is not a native op.</li><li><strong>Computation is represented as data</strong> (<code>TermData</code> over <code>serde_json::Value</code>), and that representation is the serialization boundary.</li><li><strong><code>exec_model.hnl</code></strong> is the scheme interpreter over VM primitives.</li><li><strong><code>arrow_model.hnl</code></strong> implements all <code>Term</code> tags of the arrow calculus.</li><li><strong><code>type_model.hnl</code></strong> implements the HoTT type judgments.</li><li><strong><code>meta_model.hnl</code></strong> implements module loading and evaluation.</li><li><strong>The categorical picture</strong>: composition and the arrow primitives are the semantics; evaluation-by-name is not.</li><li><strong>Rust keeps the VM and the model adapters</strong>; the models are handl data.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The kernel conflated the calculus with its evaluator, so the calculus was re-implemented as Rust enums and <code>match</code> arms that duplicated the data. A small bytecode VM plus handl models keeps the kernel stable and makes the calculus editable as data.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Named ops in the kernel</strong> — they are model data, not VM instructions.</li><li><strong>Rust <code>match</code> arms per <code>Term</code> tag</strong> — the models implement the tags.</li><li><strong>Dual Rust/handl models</strong> — one source of truth, the handl model.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The ISA is the ABI; changing it is a kernel change, changing a model is data.</li><li><code>TermData</code> becomes the serialization boundary for every engine.</li><li>Performance work moves to lowering and the models, not the kernel.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>kernel/</code> — the bytecode VM and value representation.</li><li><code>project/design/adr0103/*.hnl</code> — <code>exec_model</code>, <code>arrow_model</code>, <code>type_model</code>, <code>meta_model</code>.</li><li><code>engine-exec-*</code> — the interpreters that agree value-for-value.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The insight, architecture, ISA, serialization boundary and the model suite: +<a href="./../design/0103-kernel-is-evaluator-not-calculus.html"><code>design/0103-kernel-is-evaluator-not-calculus.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};